type DisabledReasonCode int32

const (
	DisabledReasonCode_DISABLED_REASON_CODE_UNSPECIFIED DisabledReasonCode = 0
	// The action, bonus action or reaction the option needs is already spent.
	DisabledReasonCode_DISABLED_REASON_CODE_ACTION_USED       DisabledReasonCode = 1
	DisabledReasonCode_DISABLED_REASON_CODE_BONUS_ACTION_USED DisabledReasonCode = 2
	DisabledReasonCode_DISABLED_REASON_CODE_REACTION_USED     DisabledReasonCode = 3
	// No free slot at the spell's level or above (see min_level).
	DisabledReasonCode_DISABLED_REASON_CODE_NO_SLOT DisabledReasonCode = 4
	// The feature's uses are spent (see recharge).
	DisabledReasonCode_DISABLED_REASON_CODE_NO_USES DisabledReasonCode = 5
	// Shield: cast only when an attack hits the caster.
	DisabledReasonCode_DISABLED_REASON_CODE_REACTION_ONLY_WHEN_HIT DisabledReasonCode = 6
	// Another reaction spell: cast only when its trigger happens.
	DisabledReasonCode_DISABLED_REASON_CODE_REACTION_ONLY DisabledReasonCode = 7
	// The casting time is a minute or more, too long for a fight.
	DisabledReasonCode_DISABLED_REASON_CODE_CASTING_TIME_TOO_LONG DisabledReasonCode = 8
	// CombatService.GetTurnOptions: the combatant is not the one on turn
	// ("fora da vez"). Every option of a combatant off turn carries it.
	DisabledReasonCode_DISABLED_REASON_CODE_NOT_YOUR_TURN DisabledReasonCode = 9
	// CombatService.GetTurnOptions: the combat is not running (still being set
	// up, or already over).
	DisabledReasonCode_DISABLED_REASON_CODE_COMBAT_NOT_ACTIVE DisabledReasonCode = 10
	// CombatService.GetTurnOptions: a player's character at 0 hit points
	// ("Caído"): it makes death saves (CombatService.RollDeathSave) instead of
	// acting.
	DisabledReasonCode_DISABLED_REASON_CODE_COMBATANT_DOWN DisabledReasonCode = 11
	// CombatService.GetTurnOptions: the combatant is out of the fight
	// ("Derrotado").
	DisabledReasonCode_DISABLED_REASON_CODE_COMBATANT_DEFEATED DisabledReasonCode = 12
	// An attack: the Attack action made all its attacks this turn (Extra
	// Attack). With a single attack per action the code is ACTION_USED.
	DisabledReasonCode_DISABLED_REASON_CODE_ATTACKS_USED DisabledReasonCode = 13
	// A feature that can be used once per turn (Action Surge, even at fighter
	// level 17 with two uses) was already used in this turn.
	DisabledReasonCode_DISABLED_REASON_CODE_ALREADY_USED_THIS_TURN DisabledReasonCode = 14
	// A spell: a spell cast with a bonus action leaves no other spell for the turn
	// except a cantrip with a casting time of 1 action, in either order (the
	// character cast a bonus action spell, or this is one and a spell was cast).
	DisabledReasonCode_DISABLED_REASON_CODE_BONUS_ACTION_SPELL_LIMIT DisabledReasonCode = 15
	// Flurry of Blows: it comes right after the Attack action, taken with a weapon
	// or an unarmed strike, and that action has not been taken yet this turn.
	DisabledReasonCode_DISABLED_REASON_CODE_ATTACK_ACTION_FIRST DisabledReasonCode = 16
)

